GLOSSARY = []
_ids = set()
for t, full, simple, tech, dom, rel in G:
    i = "g-" + "".join(ch.lower() if ch.isalnum() else "-" for ch in t).strip("-")
    assert i not in _ids, i; _ids.add(i)
    GLOSSARY.append(dict(id=i, term=t, full=full, simple=simple, technical=tech, domainId=dom, related=rel))
GLOSSARY.sort(key=lambda e: e["term"].lower())
_terms = {e["term"] for e in GLOSSARY}
MISSING_RELATED = sorted({r for e in GLOSSARY for r in e["related"] if r not in _terms})
